//! Jump tables: the two corpus switch objects, and the shapes that are NOT one.
//!
//! WHAT THIS FILE CLAIMS, AND ON WHAT. The corpus objects
//! (`corpus/obj/switch_*.O0.obj`) are GENERATED by the runner's clang in CI
//! (20.1.8) and by the local one (22.1.8), and the two lower a `switch`
//! differently. Four tests here used to assert on a *lowering* — the
//! `lea`/`movslq`/`add`/`jmp *%rax` sequence clang 22 emits — and so they were
//! green locally and red in CI (run 42164392990) while measuring nothing about
//! the decompiler. Two rules follow, and both are enforced below:
//!
//! * an assertion on a generated object is derived from the object's OWN
//!   relocations, so any clang that emits a jump table at all satisfies it;
//! * the exact local numbers (8 targets, 4 targets, the addresses) are printed
//!   as a CENSUS, not asserted, and the census says which clang built the bytes
//!   it describes.
//!
//! The lifting claims that need a fixed shape — `Terminator::Switch`, the
//! interpreter's per-case answers, the emitted C — live in
//! `jump_table_fixtures.rs`, over object bytes embedded in the test, with
//! `llvm-objdump` ground truth quoted there — including the memory-indirect
//! dispatch that must NOT become a switch.
//!
//! Ground truth for the LOCAL objects (`clang -O0` 22.1.8, the census below
//! reports what the runner's clang produced), `llvm-objdump -r
//! corpus/obj/switch_dense.O0.obj`:
//!
//! ```text
//! RELOCATION RECORDS FOR [.text]:
//! 000000000000001d IMAGE_REL_AMD64_REL32    .rdata
//! RELOCATION RECORDS FOR [.rdata]:
//! 0000000000000000 IMAGE_REL_AMD64_REL32    .text
//! 0000000000000004 IMAGE_REL_AMD64_REL32    .text
//! 0000000000000008 IMAGE_REL_AMD64_REL32    .text
//! 000000000000000c IMAGE_REL_AMD64_REL32    .text
//! 0000000000000010 IMAGE_REL_AMD64_REL32    .text
//! 0000000000000014 IMAGE_REL_AMD64_REL32    .text
//! 0000000000000018 IMAGE_REL_AMD64_REL32    .text
//! 000000000000001c IMAGE_REL_AMD64_REL32    .text
//! ```
//!
//! `llvm-objdump -s -j .rdata` gives the eight 4-byte entries, and `-d` gives
//! the dispatch and the case bodies:
//!
//! ```text
//!  0000 2e000000 3c000000 4a000000 58000000
//!  0010 66000000 74000000 82000000 90000000
//!
//!       1a: 48 8d 05 00 00 00 00   leaq (%rip), %rax   # 0x21  (REL32 -> .rdata)
//!       21: 48 63 0c 88            movslq (%rax,%rcx,4), %rcx
//!       25: 48 01 c8               addq %rcx, %rax
//!       28: ff e0                  jmpq *%rax
//!       2a: c7 44 24 0c 07 00 00 00  movl $0x7, 0xc(%rsp)
//!       32: eb 4e                  jmp 0x82
//!       34: ...                     (and so on: 0x3e, 0x48, 0x52, 0x5c, 0x66, 0x70)
//! ```
//!
//! So the eight case bodies this clang produced are `.text+0x2a, 0x34, 0x3e,
//! 0x48, 0x52, 0x5c, 0x66, 0x70`; `switch_fallthrough.O0.obj` is the same shape
//! with four entries and bodies at 0x32, 0x3d, 0x48, 0x55. COFF `REL32`
//! semantics give the arithmetic — the bytes at the site are the addend and the
//! linker writes `symbol + addend - (site + 4)` — so a slot at offset `s` of a
//! table based at offset `b` in its own section lands at
//! `sym_offset + addend - (s - b) - 4`: entry 0 above is `0x2e - (0 + 4 - 0) =
//! 0x2a`, entry 7 is `0x90 - (28 + 4) = 0x70`. The `.text` relocation at 0x1d
//! (`leaq (%rip)`, addend 0) is what names the table base, and it is also what
//! ties the table to a *dispatch site* — a table with no `REL32` naming it in
//! code is data, and an indirect jump with no table is still a gap.

mod common;

use common::{discover_obj, load_obj, relocated_table_targets, uncovered};
use rdec_arch_x86::discover::{overlap_free, Gap};

fn root() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn obj(rel: &str) -> std::path::PathBuf {
    root().join(rel)
}

// ---------------------------------------------------------------------------
// THE CORPUS OBJECTS, ASSERTED ON THEIR OWN RELOCATIONS ONLY.
//
// `relocated_table_targets` reads the object's `.rdata` for every
// `IMAGE_REL_AMD64_REL32 -> .text` slot and applies COFF arithmetic to the
// slot's own bytes. That list IS the object's statement of where its computed
// jumps go, so "every one of them is a discovered start" is a claim any clang
// that emits a jump table must satisfy — and the exact count for the clang that
// built these particular bytes is printed, not asserted.
// ---------------------------------------------------------------------------

/// Every slot the object relocates must be discovered and claimed, and the only
/// code discovery is allowed to leave unclaimed is a body the object itself
/// names. A lowering whose table base is not named by a `REL32` —
/// `jump_table_fixtures.rs` measures the memory-indirect form, whose naming
/// relocation is `ADDR32` — leaves its case bodies unreachable, and that has to
/// be visible as bytes whose addresses the relocations name, not as a silent
/// hole in a percentage.
fn assert_relocation_named_targets_are_discovered(rel: &str) {
    let o = load_obj(env!("CARGO_MANIFEST_DIR"), rel);
    let named = relocated_table_targets(&o, ".rdata");
    let (_o, plan, tables) = discover_obj(&obj(rel));
    let unc = uncovered(&_o, &plan, ".text");

    // CENSUS (local numbers, reported not asserted): the clang that built this
    // object, how many slots it relocated, the exact targets, the sites where a
    // table resolved, and what coverage left behind.
    let clang = std::fs::read_to_string(root().join("corpus/manifest.tsv"))
        .ok()
        .and_then(|m| {
            m.lines()
                .find(|l| l.starts_with("# clang:"))
                .map(|l| l.to_string())
        })
        .unwrap_or_else(|| "# clang: <corpus/manifest.tsv not built>".to_string());
    println!(
        "CENSUS {rel} [{clang}]\n  {} relocated .rdata slots -> {:?}\n  tables resolved at \
         {:?}, {} uncovered .text bytes: {:?}",
        named.len(),
        named
            .iter()
            .map(|(_, t)| format!("{t:#x}"))
            .collect::<Vec<_>>(),
        tables.keys().collect::<Vec<_>>(),
        unc.iter().map(|(_, l)| l).sum::<usize>(),
        unc
    );

    assert!(
        !named.is_empty(),
        "{rel}: the object relocates no .rdata slot into .text, so the assertions below \
         would check nothing. A switch lowered without a jump table (a bitset test chain) \
         must be measured by a test that says so, not by this one passing vacuously."
    );
    let bodies: Vec<u64> = named.iter().map(|(_, t)| *t).collect();
    if tables.is_empty() {
        // This clang named its table with something the recognition rule does not
        // read - `jump_table_fixtures.rs` measures that object: the memory-indirect
        // dispatch's naming relocation is `ADDR32`, not `REL32`. Nothing here may
        // read as success: the dispatch has to be a COUNTED gap, and the code it
        // strands has to show up as unclaimed bytes.
        assert_eq!(
            plan.gap_count(Gap::IndirectBranch),
            1,
            "{rel}: no table resolved from this lowering's relocations, so the indirect \
             jump must be counted as a gap, and it is not: {:?}",
            plan.gaps
        );
        assert!(
            !unc.is_empty(),
            "{rel}: no table resolved and no indirect-jump gap, yet every byte is claimed - \
             the case bodies are reachable from nothing, and coverage said nothing about it"
        );
    } else {
        // The table was named by a `REL32`, so every slot the object relocates must
        // be a discovered start: this is the claim M1's coverage makes, and it is
        // the object's own list, not a remembered count.
        for (slot, target) in &named {
            assert!(
                plan.blocks.contains(target) || plan.insns.iter().any(|&(a, _)| a == *target),
                "{rel}: .rdata slot {slot:#x} names {target:#x}, which discovery did not \
                 claim as a start; blocks are {:?}",
                plan.blocks
            );
        }
        assert_eq!(
            plan.gap_count(Gap::IndirectBranch),
            0,
            "{rel}: a table resolved, so the dispatch is not an unknown indirect jump: {:?}",
            plan.gaps
        );
    }
    // A resolved table is complete or it is reported: never half a switch.
    for t in &plan.tables {
        assert!(
            t.unresolved.is_empty(),
            "{rel}: the table at {:#x} is half-resolved: {:?}",
            t.site,
            t.unresolved
        );
    }
    assert_eq!(
        plan.gap_count(Gap::PartialTable),
        0,
        "{rel}: a half-recovered table: {:?}",
        plan.gaps
    );
    assert!(
        overlap_free(&plan.insns),
        "{rel}: sweeps overlapped: {:?}",
        plan.insns
    );
    // Coverage, stated version-robustly: every unclaimed run of `.text` starts
    // at a body the object's own relocations name. Discovery may miss a case
    // body whose table it cannot name; it may not miss anything else, and it may
    // not say nothing about it.
    for (off, len) in &unc {
        assert!(
            bodies.contains(off),
            "{rel}: {len} bytes at {off:#x} are unclaimed and are not a body the object's \
             relocations name (those are {bodies:?})"
        );
    }
}

#[test]
fn the_dense_switch_objects_own_relocations_name_the_targets_discovery_claims() {
    assert_relocation_named_targets_are_discovered("corpus/obj/switch_dense.O0.obj");
}

#[test]
fn the_fallthrough_switch_objects_own_relocations_name_the_targets_discovery_claims() {
    assert_relocation_named_targets_are_discovered("corpus/obj/switch_fallthrough.O0.obj");
}

#[test]
fn an_indirect_jump_with_no_relocation_behind_it_stays_a_counted_gap() {
    // No REL32 in code names a data base, so there is no table: the bucket is
    // the one the gate already prints. `jmp *%rax` = ff e0.
    let bytes = vec![0x48, 0x8b, 0x01, 0xff, 0xe0];
    let o = common::fixture(&[
        (".text", 0x6000_0020, &bytes),
        (".rdata", 0x4050_0040, &[0u8; 8]),
    ]);
    let (_o, plan, tables) = common::discover_fixture(&o);
    assert!(
        tables.is_empty(),
        "no relocation names a table base: {tables:?}"
    );
    assert_eq!(plan.gap_count(Gap::IndirectBranch), 1, "{:?}", plan.gaps);
}

#[test]
fn a_vtable_is_not_a_jump_table() {
    // The vtable shape: 8-byte slots, `IMAGE_REL_AMD64_ADDR64` (type 1) per
    // slot - `corpus/cpp/obj`'s virtual dispatch. A `jmp *%rax` that reads a
    // slot of it is a thunk/vtable dispatch, NOT a computed jump over a
    // relocation-covered 4-byte table, and must stay in the counted bucket.
    let text = vec![0x48, 0x8b, 0x01, 0xff, 0xe0]; // mov (%rcx),%rax; jmp *%rax
    let rdata = vec![0u8; 16]; // two 8-byte slots
    let o = common::fixture_with_relocs(
        &[
            (".text", 0x6000_0020, &text),
            (".rdata", 0x4050_0040, &rdata),
        ],
        &[(1, 0x0, 1u16, 0), (1, 0x8, 1, 0)], // ADDR64 -> .text per slot
    );
    let (_o, plan, tables) = common::discover_fixture(&o);
    assert!(
        tables.is_empty(),
        "an 8-byte ADDR64 table is not a 4-byte REL32 jump table: {tables:?}"
    );
    assert_eq!(plan.gap_count(Gap::IndirectBranch), 1, "{:?}", plan.gaps);
}

#[test]
fn cpp_virtual_dispatch_objects_yield_no_jump_tables() {
    // Real C++ objects: the indirect sites are vtable CALLS, the data is
    // 8-byte/ADDR64, and nothing here is a jump table.
    let dir = root().join("corpus/cpp/obj");
    let mut files: Vec<std::path::PathBuf> = std::fs::read_dir(&dir)
        .expect("corpus/cpp/obj")
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().map(|x| x == "obj").unwrap_or(false))
        .collect();
    files.sort();
    assert!(files.len() >= 10, "the C++ corpus is present");
    let mut calls = 0usize;
    let mut tables = 0usize;
    for f in &files {
        let (_o, plan, t) = discover_obj(f);
        tables += t.len();
        calls += plan.gap_count(Gap::IndirectCall);
        assert!(
            plan.tables.is_empty(),
            "{}: a jump table was resolved in a C++ object: {:?}",
            f.display(),
            plan.tables
        );
    }
    assert_eq!(tables, 0, "no C++ object in the corpus has a jump table");
    assert!(calls > 0, "the C++ objects do have indirect vtable calls");
}

#[test]
fn a_partially_resolved_table_is_reported_partially_resolved() {
    // Three 4-byte entries, all covered by REL32 -> .text, but entry 1's symbol
    // is UNDEFINED (section 0): no address to name. The two good targets are
    // discovered, and the site is a counted, named gap - not a silent success.
    //   0: leaq (%rip),%rax   (48 8d 05 <rel32 -> .rdata>)
    //   7: movslq (%rax,%rcx,4),%rcx  (48 63 0c 88)
    //   b: addq %rcx,%rax             (48 01 c8)
    //   e: jmpq *%rax                 (ff e0)
    //  10: c3                         ret
    //  11: c3                         ret
    //  12: c3                         ret
    let text: Vec<u8> = vec![
        0x48, 0x8d, 0x05, 0x00, 0x00, 0x00, 0x00, // leaq (%rip),%rax
        0x48, 0x63, 0x0c, 0x88, // movslq (%rax,%rcx,4),%rcx
        0x48, 0x01, 0xc8, // addq %rcx,%rax
        0xff, 0xe0, // jmpq *%rax
        0xc3, 0xc3, 0xc3, // three case bodies, 1 byte each
    ];
    // addends: COFF REL32 in a table gives target = sym_off + addend - slot - 4,
    // so entry 0 -> 0x10, entry 2 -> 0x12. Entry 1 names `far`, which this
    // object does not define: no address exists to name.
    let rdata: Vec<u8> = vec![
        0x14, 0x00, 0x00, 0x00, // -> .text+0x10
        0x15, 0x00, 0x00, 0x00, // -> `far`: undefined here
        0x1e, 0x00, 0x00, 0x00, // -> .text+0x12
    ];
    let o = common::fixture_with_relocs_full(
        &[
            (".text", 0x6000_0020, &text),
            (".rdata", 0x4050_0040, &rdata),
        ],
        &[
            (0, 0x3, 4u16, 1), // .text+0x3: the leaq's displacement -> .rdata
            (1, 0x0, 4, 2),    // entry 0 -> `f` (.text+0)
            (1, 0x4, 4, 3),    // entry 1 -> `far` (undefined)
            (1, 0x8, 4, 2),    // entry 2 -> `f`
        ],
        &[
            (".text", 1, 0, 3),
            (".rdata", 2, 0, 3),
            ("f", 1, 0, 2),
            ("far", 0, 0, 2),
        ],
    );
    let (_o, plan, tables) = common::discover_fixture(&o);
    let t = tables.get(&0xe).unwrap_or_else(|| {
        panic!(
            "no table at the dispatch 0xe: {:?}",
            tables.keys().collect::<Vec<_>>()
        )
    });
    assert_eq!(t.entries, 3, "three consecutive REL32 slots");
    assert_eq!(t.targets, vec![0x10, 0x12], "the two entries that resolve");
    assert_eq!(
        t.unresolved.len(),
        1,
        "one slot named no address: {:?}",
        t.unresolved
    );
    assert_eq!(
        plan.gap_count(Gap::PartialTable),
        1,
        "a partially-resolved table is a counted gap: {:?}",
        plan.gaps
    );
    assert_eq!(
        plan.gap_count(Gap::IndirectBranch),
        0,
        "the site is reported as the partial table, not as an unknown indirect jump"
    );
    // The resolved bodies are still claimed, because coverage is coverage.
    assert!(
        plan.blocks.contains(&0x10) && plan.blocks.contains(&0x12),
        "{:?}",
        plan.blocks
    );
}

// ---------------------------------------------------------------------------
// THE IR, THE VERIFIER AND THE INTERPRETER: hand-built, no compiler in the loop.
// ---------------------------------------------------------------------------

use rdec_core::interp::{run, Fault, Outcome, Val};
use rdec_core::ir::{Function, Op, Terminator};
use rdec_core::ty::Ty;
use rdec_core::verify::verify_ssa;

#[test]
fn an_index_the_table_covers_nothing_for_faults_and_never_guesses() {
    // A machine code jump table covers exactly the slots it has. An index at or
    // past the end names no destination this function owns, so the model stops
    // the run on a fault - never a fallthrough, never a picked block.
    //
    // This is IR built by hand, three blocks, so the rule is pinned with no
    // bounds guard in the way: `switch_dense`'s own `subq $0x7,%rax; ja` hides
    // the case by routing out-of-range inputs to `.Ldefault` before the `jmp`.
    let mut f = Function::new("sw", 0);
    let e = f.entry;
    let idx = f.emit(e, Op::Param, Ty::i64(), 0);
    // `Op::Param` alone does not bind an input; the interpreter binds what
    // `params` lists, in order.
    f.params.push(idx);
    let one = f.new_block(1);
    let two = f.new_block(2);
    let three = f.new_block(3);
    let a = f.emit(one, Op::Const(101), Ty::i64(), 1);
    f.block_mut(one).term = Terminator::Return(a);
    let b = f.emit(two, Op::Const(202), Ty::i64(), 2);
    f.block_mut(two).term = Terminator::Return(b);
    f.block_mut(e).term = Terminator::Switch {
        index: idx,
        targets: vec![one, two],
    };
    f.block_mut(three).term = Terminator::Unreachable;
    verify_ssa(&f).expect("a switch over real blocks verifies");
    assert_eq!(run(&f, &[0]).outcome, Outcome::Ret(Val::Int(101)));
    assert_eq!(run(&f, &[1]).outcome, Outcome::Ret(Val::Int(202)));
    assert_eq!(
        run(&f, &[2]).outcome,
        Outcome::Fault(Fault::SwitchOutOfRange { index: 2, len: 2 }),
        "slot 2 of a 2-slot table faults, it does not reach bb3"
    );
    assert_eq!(
        run(&f, &[u64::MAX]).outcome,
        Outcome::Fault(Fault::SwitchOutOfRange {
            index: u64::MAX,
            len: 2
        })
    );
}

#[test]
fn a_switch_target_that_is_not_a_block_of_the_function_fails_verification() {
    // The claim "every declared target exists in the function's block set" is
    // the verifier's, not the lifter's promise: a target outside the block set -
    // an address the table named that lifting never turned into a block - must
    // stop the function, not ride through as a gap.
    let mut f = Function::new("sw", 0);
    let e = f.entry;
    let idx = f.emit(e, Op::Param, Ty::i64(), 0);
    f.params.push(idx);
    let one = f.new_block(1);
    f.block_mut(one).term = Terminator::Return(idx);
    // Slot 0 names a real block, slot 1 names block id 9 of a 2-block function.
    f.block_mut(e).term = Terminator::Switch {
        index: idx,
        targets: vec![one, 9],
    };
    let err = verify_ssa(&f)
        .expect_err("a switch target outside the block set")
        .join("\n");
    assert!(
        err.contains("not a block of this function"),
        "the verifier names the slot: {err}"
    );
    // And a switch over nothing at all - the shape a table with no resolved slot
    // leaves behind - has no successor, so it is not control flow.
    let mut g = Function::new("empty", 0);
    let ge = g.entry;
    let gi = g.emit(ge, Op::Param, Ty::i64(), 0);
    g.params.push(gi);
    g.block_mut(ge).term = Terminator::Switch {
        index: gi,
        targets: vec![],
    };
    let err = verify_ssa(&g)
        .expect_err("an empty target list is not control flow")
        .join("\n");
    assert!(
        err.contains("empty target list"),
        "the verifier says why: {err}"
    );
}
